/* @lc app=leetcode id=2477 lang=kotlin */
class Solution { fun minimumFuelCost(roads: Array<IntArray>, seats: Int): Long = Array(roads.size + 1) { mutableListOf<Int>() }.also { adj -> roads.forEach { adj[it[0]].add(it[1]).also { _ -> adj[it[1]].add(it[0]) } } }.let { adj -> LongArray(1).let { fuel -> kotlin.DeepRecursiveFunction<Pair<Int, Int>, Long> { (u, p) -> adj[u].filter { it != p }.sumOf { callRecursive(it to u) }.plus(1).also { size -> if (u != 0) fuel[0] += (size + seats - 1) / seats } }.invoke(0 to -1).run { fuel[0] } } } }